    limNoted:   { roman: "You'll be told", deva: "आपको बता दिया जायेगा", telugu: "మీకు తెలియజేస్తాం" },
    limNotNow:  { roman: "Not now", deva: "अभी नहीं", telugu: "ఇప్పుడు కాదు" },
    limFreeOne: { roman: "one free this month", deva: "इस मास एक नि:शुल्क", telugu: "ఈ నెల ఒకటి ఉచితం" },
    limFreeLeft:{ roman: "This month's free one — used. Back next month.", deva: "इस महीने की मुफ़्त सीमा पूरी हुई — अगले महीने फिर।", telugu: "ఈ నెల ఉచితం వాడారు — వచ్చే నెల మళ్ళీ." },

    /* dakṣiṇā — asked for, never charged; nothing in the app is held back */
    danaCap:        { roman: "Support this work", deva: "इस कार्य को सहयोग", telugu: "ఈ యాప్‌కు సహాయం" },
    danaTitle:      { roman: "Light a lamp for this work", deva: "इस कार्य के लिये एक दीप जलाइये", telugu: "ఈ యాప్‌కు సహాయం చేయండి" },
    danaLede:       { roman: "Everything here is free. There is no fee. If you can, give dakṣiṇā — that is what keeps this work going.", deva: "यहाँ सब कुछ मुफ़्त है। कोई शुल्क नहीं। जो दे सकें, दक्षिणा दें — उसी से यह काम चलता है।", telugu: "ఇక్కడ అన్నీ ఉచితం. ఏ రుసుమూ లేదు. మీకు వీలైతే దక్షిణ ఇవ్వండి — దానితోనే ఈ పని నడుస్తుంది." },
    danaWhat1:      { roman: "Typing the texts and checking them verse by verse against printed editions", deva: "पाठ टाइप करना और छपी पुस्तकों से श्लोक-श्लोक मिलाकर जाँचना", telugu: "పాఠాలను టైప్ చేసి, ముద్రిత ప్రతులతో శ్లోకం శ్లోకం సరిచూడటం" },
    danaWhat2:      { roman: "The meanings in Telugu, Hindi and English, and the thousand-name glossaries", deva: "तेलुगु, हिन्दी और अंग्रेज़ी अर्थ, तथा सहस्रनाम की नामावलियाँ", telugu: "తెలుగు, హిందీ, ఇంగ్లీషు అర్థాలు, సహస్రనామ నామావళులు" },
    danaWhat3:      { roman: "Recording forty-one stotras with a paṇḍit in a studio", deva: "पंडित के साथ स्टूडियो में इकतालीस स्तोत्रों की रिकॉर्डिंग", telugu: "పండితుడితో స్టూడియోలో నలభై ఒక్క స్తోత్రాల రికార్డింగ్‌లు" },
    danaAmtDay:     { roman: "a lamp for a day", deva: "एक दिन का दीप", telugu: "ఒక రోజు దీపం" },
