    danaAmtYear:    { roman: "a lamp for the year", deva: "वर्षभर का दीप", telugu: "సంవత్సరపు దీపం" },
    danaAmtPatron:  { roman: "patron — named in the colophon", deva: "आश्रयदाता — समापन में नाम", telugu: "పోషకుడు — సమాపనంలో పేరు" },
    danaNameLbl:    { roman: "The name to be printed", deva: "जो नाम छपे", telugu: "ముద్రించవలసిన పేరు" },
    danaNamePh:     { roman: "a name, a family, or someone remembered", deva: "नाम, कुल, या किसी की स्मृति में", telugu: "పేరు, కుటుంబం, లేదా ఎవరి స్మృతిలోనైనా" },
    danaOpenNote:   { roman: "Donations are not open yet — no money is taken today. The amounts will stay as shown.", deva: "दान लेना अभी शुरू नहीं हुआ — आज पैसे नहीं लिए जाते। राशियाँ यही रहेंगी।", telugu: "దానం స్వీకరణ ఇంకా మొదలవలేదు — ఈరోజు డబ్బు తీసుకోము. మొత్తాలు ఇవే ఉంటాయి." },
