    danaNotNow:     { roman: "Not now", deva: "अभी नहीं", telugu: "ఇప్పుడు కాదు" },
    danaNothingHeld:{ roman: "Nothing is held back", deva: "कुछ रोका नहीं गया", telugu: "ఏదీ ఆపబడలేదు" },
    danaNothingHeldNote: { roman: "Every text, script, meaning, glossary, the pañcāṅga, print and share — free for everyone, whether you give or not.", deva: "हर स्तोत्र, लिपि, अर्थ, नामावली, पंचांग, प्रिंट और शेयर — सबके लिए मुफ़्त, दान दें या न दें।", telugu: "ప్రతి స్తోత్రం, ప్రతి లిపి, ప్రతి అర్థం, నామావళులు, పంచాంగం, ముద్రణ, పంచుకోవడం — అందరికీ ఉచితం — దానం ఇచ్చినా ఇవ్వకపోయినా." },
    danaSoonTitle:  { roman: "The giving is not open yet", deva: "दान अभी आरम्भ नहीं हुआ", telugu: "దానం ఇంకా ప్రారంభం కాలేదు" },
    danaSoonBody:   { roman: "No money is taken now and no card is asked for. Leave your name and we will tell you the day it opens.", deva: "अभी पैसे नहीं लिए जाते, कार्ड भी नहीं माँगा जाता। नाम दें — शुरू होने पर बता देंगे।", telugu: "ఇప్పుడు డబ్బు తీసుకోము, కార్డు అడగము. పేరు ఇవ్వండి — మొదలైన రోజు తెలియజేస్తాం." },
    danaRails:      { roman: "When it opens: UPI and cards on the website; store billing in the apps.", deva: "शुरू होने पर — वेबसाइट पर UPI और कार्ड; ऐप में स्टोर से भुगतान।", telugu: "ప్రారంభమైనప్పుడు — వెబ్‌సైట్‌లో UPI, కార్డులు; యాప్‌లో స్టోర్ చెల్లింపు." },
    danaNotify:     { roman: "Tell me when it opens", deva: "आरम्भ होने पर बताइये", telugu: "ప్రారంభమైనప్పుడు చెప్పండి" },
    danaNoted:      { roman: "You'll be told", deva: "आपको बता दिया जायेगा", telugu: "మీకు తెలియజేస్తాం" },
    danaMarkLit:    { roman: "I've given — light the lamp", deva: "मैंने दिया — दीप जलाइये", telugu: "నేను ఇచ్చాను — దీపం వెలిగించండి" },
    danaPreviewLamp:{ roman: "Light the lamp as a preview", deva: "दीप को पूर्वावलोकन रूप में जलाइये", telugu: "దీపాన్ని ప్రివ్యూగా వెలిగించండి" },
    danaLitTitle:   { roman: "Your lamp is burning", deva: "आपका दीप जल रहा है", telugu: "మీ దీపం వెలుగుతోంది" },
    danaLitSub:     { roman: "It stays on the home screen. When donations open, the name goes into the credits page.", deva: "यह होम स्क्रीन पर रहेगा; दान शुरू होने पर नाम समापन पृष्ठ में जाएगा।", telugu: "ఇది గృహపేజీలో ఉంటుంది; దానం ప్రారంభమైనప్పుడు పేరు సమాపనంలో చేరుతుంది." },
