    danaRowSub:     { roman: "Nothing is withheld — a lamp, if you can", deva: "सब मुफ़्त — हो सके तो दक्षिणा दें", telugu: "అన్నీ ఉచితం — వీలైతే దక్షిణ ఇవ్వండి" },
