    fbKind_problem: { roman: "Something is broken", deva: "कुछ बिगड़ा है", telugu: "ఏదో పని చేయడం లేదు" },
    fbKind_idea:    { roman: "An idea", deva: "एक सुझाव", telugu: "ఒక సూచన" },
