    fbPlaceholder_idea:    { roman: "e.g. the Bajaraṅga Bāṇa, and a Marāṭhī gloss", deva: "उदा. बजरंग बाण, और मराठी अर्थ", telugu: "ఉదా. బజరంగ బాణ, మరాఠీ అర్థం" },
    fbPlaceholder_text:    { roman: "e.g. Liṅgāṣṭakam verse 3 — our edition reads janmaja instead", deva: "उदा. लिङ्गाष्टक श्लोक 3 — हमारे संस्करण में 'जन्मज' है", telugu: "ఉదా. లింగాష్టకం 3వ శ్లోకం — మా ప్రతిలో 'జన్మజ' ఉంది" },
