    "Kṛṣṇa Yajurveda":     { deva: "कृष्ण यजुर्वेद",        telugu: "కృష్ణ యజుర్వేద" },
    "Mārkaṇḍeya Purāṇa":   { deva: "मार्कण्डेय पुराण",      telugu: "మార్కండేయ పురాణ" },
    "Muttusvāmī Dīkṣitar": { deva: "मुत्तुस्वामी दीक्षितर्", telugu: "ముత్తుస్వామి దీక్షితర్" },
