    "Totakācārya":         { deva: "तोटकाचार्य",            telugu: "తోటకాచార్య" },
    "Vallabhācārya":       { deva: "वल्लभाचार्य",           telugu: "వల్లభాచార్య" },
    "Agastya":             { deva: "अगस्त्य",               telugu: "అగస్త్య" },
    "Aṇṇangarācārya":      { deva: "अण्णङ्गराचार्य",        telugu: "అణ్ణంగరాచార్య" },
    "Bilvamaṅgala":        { deva: "बिल्वमङ्गल",            telugu: "బిల్వమంగల" },
    "Brahmāṇḍa Purāṇa":    { deva: "ब्रह्माण्ड पुराण",       telugu: "బ్రహ్మాండ పురాణ" },
