    "Devarāya Svāmigaḷ":   { deva: "देवराय स्वामिगळ्",       telugu: "దేవరాయ స్వామిగళ్" },
    "Devī Māhātmya":       { deva: "देवी माहात्म्य",         telugu: "దేవీ మాహాత్మ్య" },
    "Jayadeva":            { deva: "जयदेव",                telugu: "జయదేవ" },
    "Kālidāsa":            { deva: "कालिदास",              telugu: "కాలిదాస" },
    "Kulaśekhara Āḻvār":   { deva: "कुलशेखर आऴ्वार्",        telugu: "కులశేఖర ఆళ్వార్" },
    "Līlāśuka":            { deva: "लीलाशुक",              telugu: "లీలాశుక" },
    "Mārkaṇḍeya":          { deva: "मार्कण्डेय",            telugu: "మార్కండేయ" },
    "Nārada":              { deva: "नारद",                telugu: "నారద" },
    "Nārada Purāṇa":       { deva: "नारद पुराण",           telugu: "నారద పురాణ" },
    "Padma Purāṇa":        { deva: "पद्म पुराण",            telugu: "పద్మ పురాణ" },
    "Puṣpadanta":          { deva: "पुष्पदन्त",             telugu: "పుష్పదంత" },
    "Rāmakṛṣṇa Kavi":      { deva: "रामकृष्ण कवि",          telugu: "రామకృష్ణ కవి" },
    "Rāvaṇa":              { deva: "रावण",                 telugu: "రావణ" },
    "Samartha Rāmdās":     { deva: "समर्थ रामदास",          telugu: "సమర్థ రామదాస" },
    "Sāmba":               { deva: "साम्ब",                telugu: "సాంబ" },
    "Skanda Purāṇa":       { deva: "स्कन्द पुराण",          telugu: "స్కంద పురాణ" },
    "Vibhīṣaṇa":           { deva: "विभीषण",               telugu: "విభీషణ" },
    "Viśvāmitra":          { deva: "विश्वामित्र",           telugu: "విశ్వామిత్ర" },
